"use strict";(globalThis.webpackChunkopenember_docs=globalThis.webpackChunkopenember_docs||[]).push([[1536],{9027(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/en/docs/intro","label":"What is OpenEmber?","docId":"intro","unlisted":false},{"type":"link","href":"/en/docs/architecture-overview","label":"Architecture overview","docId":"architecture-overview","unlisted":false},{"type":"link","href":"/en/docs/detection-and-response","label":"Detection, response, and recovery","docId":"detection-and-response","unlisted":false},{"type":"link","href":"/en/docs/product-quickstart","label":"Create your first product","docId":"product-quickstart","unlisted":false},{"type":"link","href":"/en/docs/alerts","label":"Shared alerts component","docId":"alerts","unlisted":false},{"type":"link","href":"/en/docs/alerts-link","label":"Alert events and Link","docId":"alerts-link","unlisted":false},{"type":"link","href":"/en/docs/launch-and-system-state","label":"Launch orchestration and system state","docId":"launch-and-system-state","unlisted":false},{"type":"link","href":"/en/docs/build-openember","label":"Build OpenEmber","docId":"build-openember","unlisted":false},{"type":"link","href":"/en/docs/configuration","label":"Build configuration and runtime parameters","docId":"configuration","unlisted":false},{"type":"link","href":"/en/docs/turtle-demo","label":"Turtle Demo (host turtlesim)","docId":"turtle-demo","unlisted":false},{"type":"link","href":"/en/docs/rover-demo","label":"Rover Demo","docId":"rover-demo","unlisted":false},{"type":"link","href":"/en/docs/agri-station-demo","label":"Agri Station Demo","docId":"agri-station-demo","unlisted":false},{"type":"link","href":"/en/docs/build-emberlite","label":"Build EmberLite","docId":"build-emberlite","unlisted":false},{"type":"link","href":"/en/docs/cli-ember","label":"ember CLI","docId":"cli-ember","unlisted":false},{"type":"link","href":"/en/docs/openember-msgs","label":"openember-msgs protocol","docId":"openember-msgs","unlisted":false},{"type":"link","href":"/en/docs/openember-algorithm","label":"OpenEmber Algorithm","docId":"openember-algorithm","unlisted":false},{"type":"link","href":"/en/docs/openember-link","label":"OpenEmber Link","docId":"openember-link","unlisted":false},{"type":"link","href":"/en/docs/openember-thread-pool","label":"OpenEmber Thread Pool","docId":"openember-thread-pool","unlisted":false},{"type":"link","href":"/en/docs/openember-logging","label":"OpenEmber Logging","docId":"openember-logging","unlisted":false},{"type":"link","href":"/en/docs/rbu-specification","label":"RBU Specification","docId":"rbu-specification","unlisted":false},{"type":"category","label":"\u7f16\u7a0b\u98ce\u683c","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/en/docs/styleguide/cpp-style-guide","label":"OpenEmber C++ Coding Style Guide","docId":"styleguide/cpp-style-guide","unlisted":false},{"type":"link","href":"/en/docs/styleguide/c-style-guide","label":"EmberLite C Coding Style Guide","docId":"styleguide/c-style-guide","unlisted":false}]}]},"docs":{"agri-station-demo":{"id":"agri-station-demo","title":"Agri Station Demo","description":"Third product demo openember docs/design/agri-station-demo.md.","sidebar":"tutorialSidebar"},"alerts":{"id":"alerts","title":"Shared alerts component","description":"OpenEmber core components/alerts provides in-process alert state, an event queue, and async log dispatch. CMake target openember::alerts, header `. Toggle with Kconfig/CMake OPENEMBERCOMPONENTALERTS` (on by default). Detection algorithms, threshold hysteresis/debounce, and reminder periods belong to detectors; the alerts component does not take control authority and does not stop, latch, or recover.","sidebar":"tutorialSidebar"},"alerts-link":{"id":"alerts-link","title":"Alert events and Link","description":"Alerts and logs use two independent output paths: alerts \u2192 logging \u2192 spdlog TopicSink \u2192 log topic for troubleshooting; alerts \u2192 LinkPublisher \u2192 structured alert topics for whole-machine state managers, UIs, and ops subscribers. TopicSink publishes logs only\u2014it is not an alert protocol. Detection, whole-machine response, and execution arbitration stay separate; subscribers must not derive a fixed stop action from log level.","sidebar":"tutorialSidebar"},"architecture-overview":{"id":"architecture-overview","title":"Architecture overview","description":"OpenEmber currently uses a clear four-layer model (dependencies flow downward) for extension and long-term maintenance:","sidebar":"tutorialSidebar"},"build-emberlite":{"id":"build-emberlite","title":"Build EmberLite","description":"EmberLite uses CMake (3.16 or newer recommended) and, optionally, the same Kconfig \u2192 build/.config \u2192 build/config.cmake flow as OpenEmber to manage feature switches.","sidebar":"tutorialSidebar"},"build-openember":{"id":"build-openember","title":"Build OpenEmber","description":"OpenEmber uses Kconfig to produce build/.config. Scripts then generate build/config.cmake, which CMake reads to drive the build. Linux with GCC/G++ is recommended. The minimum CMake version is whatever the repository CMakeLists.txt currently requires.","sidebar":"tutorialSidebar"},"cli-ember":{"id":"cli-ember","title":"ember CLI","description":"OpenEmber ships scripts/ember. The standalone openember-cli repository also provides ember. Capabilities depend on the version; prefer the copy bundled with the framework for product creation and model workflows. The framework root provides scripts/kconfig/. A standalone product reaches those scripts through the openember/ dependency and does not need its own copy of the toolchain.","sidebar":"tutorialSidebar"},"configuration":{"id":"configuration","title":"Build configuration and runtime parameters","description":"OpenEmber separates build-time capabilities from device runtime parameters. Kconfig with CMake decides what the program includes; YAML decides which parameters already-built modules run with. Products may integrate the framework from source or develop inside the framework tree\u2014this split does not change with the engineering mode.","sidebar":"tutorialSidebar"},"detection-and-response":{"id":"detection-and-response","title":"Detection, response, and recovery","description":"Robots and smart devices often need to detect tilt, temperature, collision, tracking error, input loss, or communication loss. The same phenomenon may require different responses across tasks: a large tilt angle may mean a tip-over\u2014or a planned climb/flip. Keep fact detection, response decisions, and action execution separate so detectors never hard-bind whole-machine stop, fault latch, or process exit.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"What is OpenEmber?","description":"OpenEmber is a runtime framework for robotics and intelligent devices on Linux. It provides a unified communication backbone, a hardware abstraction layer (HAL), and a node execution model for building distributed embedded systems.","sidebar":"tutorialSidebar"},"launch-and-system-state":{"id":"launch-and-system-state","title":"Launch orchestration and system state","description":"OpenEmber separates process lifecycle from product state. By default launchmanager creates a local Link router and ordinary nodes join as clients; standalone debug programs may create their own router. Whole-machine state management is a separate service: shared aggregation lives in components/systemstate, while model rules and execution logic belong to the product.","sidebar":"tutorialSidebar"},"openember-algorithm":{"id":"openember-algorithm","title":"OpenEmber Algorithm","description":"components/algorithm is OpenEmber\'s lightweight general-purpose algorithm library for the high-frequency primitives used in intelligent devices, robots, and edge runtimes.","sidebar":"tutorialSidebar"},"openember-link":{"id":"openember-link","title":"OpenEmber Link","description":"OpenEmber Link is the stable communication layer for nodes, tools, system services, and device management. Upward it provides topics, services, liveliness, node discovery, and diagnostics. Downward it hides the concrete middleware. Application code should program against OpenEmber communication semantics, not against Zenoh mode, endpoint, key expression, or session details.","sidebar":"tutorialSidebar"},"openember-logging":{"id":"openember-logging","title":"OpenEmber Logging","description":"components/logging is OpenEmber\'s in-process logging component. The C++ API is openember::Logger. Application code keeps using the LOG and OE_LOG macros.","sidebar":"tutorialSidebar"},"openember-msgs":{"id":"openember-msgs","title":"openember-msgs protocol","description":"openember-msgs is the message-protocol repository shared by OpenEmber and EmberLite. It stores .proto definitions, Nanopb constraints, and the generation entry points. It does not implement the OpenEmber or EmberLite runtime.","sidebar":"tutorialSidebar"},"openember-thread-pool":{"id":"openember-thread-pool","title":"OpenEmber Thread Pool","description":"components/thread_pool is OpenEmber\'s fixed-size thread pool. Use it to run short tasks asynchronously inside a node (for example parsing inside a message callback, or non-real-time post-processing) without blocking the main loop or a communication thread.","sidebar":"tutorialSidebar"},"product-quickstart":{"id":"product-quickstart","title":"Create your first product","description":"OpenEmber supports three engineering modes: maintain the framework source tree directly, integrate the framework source into an independent product and build together, and\u2014planned\u2014develop against an installed SDK. The first two already have entry points; the third is for later SDK delivery.","sidebar":"tutorialSidebar"},"rbu-specification":{"id":"rbu-specification","title":"RBU Specification 1.0","description":"RBU (Robot Bundle Update) is a multi-component release description and update-bundle format for robots and complex intelligent devices. It aggregates, describes, verifies, and orchestrates update artifacts. It does not replace Debian packages, a Linux image, or an MCU firmware format.","sidebar":"tutorialSidebar"},"rover-demo":{"id":"rover-demo","title":"Rover Demo","description":"This page describes the planned second product demo: a differential-drive rover. The app is intended to live at apps/rover_demo. Design details are in the openember repo at docs/design/rover-demo.md. Build and run steps will be added here once code and launch files land.","sidebar":"tutorialSidebar"},"styleguide/c-style-guide":{"id":"styleguide/c-style-guide","title":"EmberLite C Coding Style Guide","description":"General principles","sidebar":"tutorialSidebar"},"styleguide/cpp-style-guide":{"id":"styleguide/cpp-style-guide","title":"OpenEmber C++ Coding Style Guide","description":"General principles","sidebar":"tutorialSidebar"},"turtle-demo":{"id":"turtle-demo","title":"Turtle Demo (host turtlesim)","description":"apps/turtle_demo is a turtlesim-style demo for x86 Linux hosts. It needs no target board or real hardware. Two processes show OpenEmber multi-node Link, Protobuf messages, and optional launch orchestration. An SDL2 window is the default view; use --no-gui when headless.","sidebar":"tutorialSidebar"}}}}')}}]);